"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.  Two rules follow from that:

* every address and every length is reported with the full width the target
  process uses -- a 6 GiB reservation on a 64 bit process is 6442450944
  bytes, not that value modulo 2**32;
* every file name is reported the way the caller can open it (``C:\\...`` or
  ``\\\\server\\share\\...``), never as the NT device name the system hands
  out internally, and never as an empty string standing in for "no file".
"""

import ctypes
import os
import string

from .errors import WVasError

try:  # pragma: no cover - only taken on a platform without the Win32 API
    from . import _winapi as w
except Exception as exc:  # ImportError / OSError / AttributeError
    w = None
    _PLATFORM_PROBLEM = "address space auditing needs the Win32 API: %s" % (exc,)
else:
    _PLATFORM_PROBLEM = None

# GetMappedFileNameW happily needs more than MAX_PATH on a deep tree.
PATH_BUFFER_CHARS = 32768

# Fallback upper bound of the user address space, used when the system does
# not tell us one.  The walk stops as soon as VirtualQueryEx refuses an
# address, so this is only a safety net against a runaway loop.
_MAX_APPLICATION_ADDRESS = 0x7FFFFFFEFFFF

# The PAGE_* and MEM_* constants spelled out so that the two naming helpers
# stay pure functions: they must not touch a process, and they must keep
# working even where the Win32 bindings cannot be imported at all.
_PROTECTION_NAMES = {
    0x01: "none",  # PAGE_NOACCESS
    0x02: "r",     # PAGE_READONLY
    0x04: "rw",    # PAGE_READWRITE
    0x08: "wc",    # PAGE_WRITECOPY
    0x10: "x",     # PAGE_EXECUTE
    0x20: "xr",    # PAGE_EXECUTE_READ
    0x40: "xrw",   # PAGE_EXECUTE_READWRITE
    0x80: "xwc",   # PAGE_EXECUTE_WRITECOPY
}

_TYPE_NAMES = {
    0x1000000: "image",   # MEM_IMAGE
    0x40000: "mapped",    # MEM_MAPPED
    0x20000: "private",   # MEM_PRIVATE
}

_MEM_IMAGE = 0x1000000
_MEM_MAPPED = 0x40000

# Namespace aliases that are not openable by a caller.
_NAMESPACE_ALIASES = ("\\??\\", "\\dosdevices\\", "\\\\?\\")

# The redirector devices whose children are UNC shares.
_UNC_DEVICES = (
    "\\device\\mup\\",
    "\\device\\lanmanredirector\\",
    "\\device\\windfs\\",
    "\\device\\nfsr\\",
)


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name."""
    try:
        value = int(protect)
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(value & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name."""
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# --------------------------------------------------------------------------
# platform and error plumbing
# --------------------------------------------------------------------------

def _require_platform():
    if _PLATFORM_PROBLEM is not None:
        raise WVasError(_PLATFORM_PROBLEM, kind="unsupported")
    if w.VirtualQueryEx is None or w.OpenProcess is None:
        raise WVasError(
            "this platform cannot answer address space queries",
            kind="unsupported",
        )


def _fail(message, pid, kinds=None):
    """Classify the last Win32 error and raise the matching :class:`WVasError`."""
    error = w.last_error()
    kinds = kinds or {}
    kind = kinds.get(error, "query-failed")
    raise WVasError("%s (Win32 error %d)" % (message, error), kind=kind, pid=pid)


def _open_process(pid):
    """Open ``pid`` for reading its address space, classifying every failure."""
    _require_platform()
    if isinstance(pid, bool):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    try:
        value = pid.__index__() if hasattr(pid, "__index__") else int(pid)
    except (AttributeError, TypeError, ValueError):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if not isinstance(value, int) or value != pid:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if value <= 0 or value > 0xFFFFFFFF:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)

    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, value
    )
    if not handle:
        _fail(
            "cannot open the process for reading",
            value,
            kinds={
                w.ERROR_ACCESS_DENIED: "access-denied",
                w.ERROR_INVALID_PARAMETER: "no-such-process",
            },
        )
    return handle


# --------------------------------------------------------------------------
# turning NT device names into paths the caller can open
# --------------------------------------------------------------------------

def _is_openable(path):
    """True when ``path`` is a DOS drive path or a UNC path a caller can open."""
    if not path:
        return False
    if path.startswith("\\\\") and not path.startswith("\\\\?\\"):
        return not path.startswith("\\\\.\\")
    return (
        len(path) >= 3
        and path[0] in string.ascii_letters
        and path[1] == ":"
        and path[2] == "\\"
    )


def _strip_extended_prefix(path):
    """Drop ``\\\\?\\`` / ``\\\\?\\UNC\\`` and keep a plain drive or UNC path."""
    if path.startswith("\\\\?\\UNC\\"):
        return "\\\\" + path[len("\\\\?\\UNC\\"):]
    if path.startswith("\\\\?\\"):
        return path[len("\\\\?\\"):]
    return path


def _dos_device_targets(name):
    """The NT device names ``name`` (a drive letter) currently points at."""
    if w.QueryDosDeviceW is None:
        return []
    buffer = ctypes.create_unicode_buffer(w.MULTI_SZ_CHARS)
    length = w.QueryDosDeviceW(name, buffer, w.MULTI_SZ_CHARS)
    if not length:
        return []
    return w.multi_sz(buffer, length)


def _dos_device_map():
    """``[(nt device name, drive letter)]``, longest device name first."""
    devices = {}
    for letter in string.ascii_uppercase:
        drive = letter + ":"
        for target in _dos_device_targets(drive):
            key = target.rstrip("\\").lower()
            if key and key not in devices:
                devices[key] = drive
    return sorted(devices.items(), key=lambda item: len(item[0]), reverse=True)


def _dos_path(name, devices):
    """Translate an NT device path into a drive letter or UNC path."""
    if not name:
        return None
    path = name.strip().replace("/", "\\")
    lowered = path.lower()

    for alias in _NAMESPACE_ALIASES:
        if lowered.startswith(alias):
            path = path[len(alias):]
            lowered = path.lower()
            break

    # \??\C:\dir\file and \\?\UNC\server\share\file are already usable.
    if _is_openable(path):
        return path
    if lowered.startswith("unc\\"):
        return "\\\\" + path[len("unc\\"):]

    if not path.startswith("\\"):
        path = "\\" + path
        lowered = path.lower()

    for unc in _UNC_DEVICES:
        if lowered.startswith(unc):
            return "\\\\" + path[len(unc):]

    for device, drive in devices:
        if lowered == device:
            return drive + "\\"
        if lowered.startswith(device + "\\"):
            return drive + "\\" + path[len(device) + 1:]
    return None


def _final_path(path):
    """The real on-disk path of ``path``, or ``None`` when it cannot be had."""
    if w.CreateFileW is None or w.GetFinalPathNameByHandleW is None:
        return None
    handle = w.CreateFileW(
        path,
        0,
        w.FILE_SHARE_READ | w.FILE_SHARE_WRITE | w.FILE_SHARE_DELETE,
        None,
        w.OPEN_EXISTING,
        w.FILE_FLAG_BACKUP_SEMANTICS,
        None,
    )
    if not handle:
        return None
    try:
        size = w.MAX_PATH
        while size <= w.PATH_BUFFER_CHARS:
            buffer = ctypes.create_unicode_buffer(size)
            written = w.GetFinalPathNameByHandleW(
                handle, buffer, size, w.VOLUME_NAME_DOS | w.FILE_NAME_NORMALIZED
            )
            if not written:
                return None
            if written < size:
                resolved = _strip_extended_prefix(buffer.value)
                return resolved if _is_openable(resolved) else None
            size = written + 1
        return None
    finally:
        w.CloseHandle(handle)


class _PathResolver:
    """Resolves the file behind a region of one target process.

    The device table and the resolved names are cached for the lifetime of a
    single audit: a process has a few hundred regions but only a handful of
    distinct files behind them.
    """

    def __init__(self, handle):
        self._handle = handle
        self._devices = None
        self._by_name = {}
        self._modules = None

    # -- lazily built tables ------------------------------------------------
    def _device_map(self):
        if self._devices is None:
            self._devices = _dos_device_map()
        return self._devices

    def _module_paths(self):
        if self._modules is None:
            self._modules = _enumerate_module_paths(self._handle)
        return self._modules

    # -- the answer ---------------------------------------------------------
    def resolve(self, base, region_type):
        """The openable path of the file behind ``base``, or ``None``."""
        name = self._mapped_name(base)
        path = None
        if name is not None:
            if name in self._by_name:
                return self._by_name[name]
            path = _dos_path(name, self._device_map())
        if path is None and region_type == _MEM_IMAGE:
            # The system did not name the file, or named it in a form we
            # cannot turn into a drive letter: the loader still knows.
            path = self._module_paths().get(base)
        if path is None or not _is_openable(path):
            resolved = None
        else:
            resolved = _final_path(path) or path
            if not _is_openable(resolved):
                resolved = None
        if name is not None:
            self._by_name[name] = resolved
        return resolved

    def _mapped_name(self, base):
        """The NT device name the system gives for the file mapped at ``base``."""
        if w.GetMappedFileNameW is None:
            return None
        size = w.MAX_PATH
        while True:
            buffer = ctypes.create_unicode_buffer(size)
            written = w.GetMappedFileNameW(
                self._handle, ctypes.c_void_p(base), buffer, size
            )
            if written:
                return buffer.value or None
            error = w.last_error()
            if error == w.ERROR_INSUFFICIENT_BUFFER and size < PATH_BUFFER_CHARS:
                size *= 4
                continue
            # Not file backed (an anonymous section, private memory) or the
            # name is not readable: there is no file to report.
            return None


def _enumerate_module_paths(handle):
    """``{module base: Win32 path}`` for the images the loader lists."""
    if w.EnumProcessModulesEx is None or w.GetModuleFileNameExW is None:
        return {}
    paths = {}
    count = 64
    for _ in range(4):
        modules = (ctypes.c_void_p * count)()
        needed = ctypes.wintypes.DWORD(0)
        ok = w.EnumProcessModulesEx(
            handle,
            modules,
            ctypes.sizeof(modules),
            ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        if ok:
            total = needed.value // ctypes.sizeof(ctypes.c_void_p)
            for index in range(min(total, count)):
                base = modules[index] or 0
                if not base or base in paths:
                    continue
                buffer = ctypes.create_unicode_buffer(w.PATH_BUFFER_CHARS)
                written = w.GetModuleFileNameExW(
                    handle,
                    ctypes.c_void_p(base),
                    buffer,
                    w.PATH_BUFFER_CHARS,
                )
                if written:
                    name = buffer.value
                    if _is_openable(name):
                        paths[base] = name
            return paths
        if w.last_error() != w.ERROR_BAD_LENGTH:
            return paths
        count *= 4
    return paths


# --------------------------------------------------------------------------
# the walk over the address space
# --------------------------------------------------------------------------

def _address_space_limit():
    if w.GetSystemInfo is None:
        return _MAX_APPLICATION_ADDRESS
    info = w.SYSTEM_INFO()
    w.GetSystemInfo(ctypes.byref(info))
    limit = info.lpMaximumApplicationAddress or 0
    return limit if limit > 0 else _MAX_APPLICATION_ADDRESS


def _walk(handle, pid, include_reserved):
    """Yield ``(descriptor, allocation base)`` for every region in use.

    The regions are reported exactly as ``VirtualQueryEx`` measures them: no
    rounding, no truncation, no merging of neighbours, so that the numbers can
    be held next to a debugger's.
    """
    resolver = _PathResolver(handle)
    limit = _address_space_limit()
    info = w.MEMORY_BASIC_INFORMATION()
    length = ctypes.sizeof(info)
    address = 0
    queried = False

    while address <= limit:
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(info), length
        )
        if not written:
            if not queried:
                _fail(
                    "cannot query the address space",
                    pid,
                    kinds={w.ERROR_ACCESS_DENIED: "access-denied"},
                )
            break
        queried = True

        base = info.BaseAddress or 0
        size = info.RegionSize or 0
        state = info.State
        region_type = info.Type

        if state == w.MEM_COMMIT or (include_reserved and state == w.MEM_RESERVE):
            descriptor = {
                "base": base,
                "size": size,
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(region_type),
                "protect": protection_name(info.Protect),
                "path": None,
                "image": region_type == _MEM_IMAGE,
            }
            if region_type in (_MEM_IMAGE, _MEM_MAPPED):
                descriptor["path"] = resolver.resolve(base, region_type)
            yield descriptor, info.AllocationBase or base

        step = base + size
        if size == 0 or step <= address:
            break
        address = step


def _audit(pid, include_reserved):
    """Run one audit of ``pid`` and return the descriptors, ascending."""
    handle = _open_process(pid)
    try:
        descriptors = [item for item, _ in _walk(handle, pid, include_reserved)]
    finally:
        w.CloseHandle(handle)
    descriptors.sort(key=lambda item: item["base"])
    return descriptors


# --------------------------------------------------------------------------
# public API
# --------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Both committed and reserved regions are reported unless
    ``include_reserved`` is false; free address space is never reported.
    """
    return _audit(pid, True if include_reserved else False)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    An image spans several regions (code, read-only data, writable data), so
    the regions belonging to one image are folded into a single entry keyed by
    the address the image was allocated at.  Each image, and each file, is
    reported exactly once.
    """
    handle = _open_process(pid)
    try:
        images = {}
        for descriptor, allocation_base in _walk(handle, pid, False):
            if not descriptor["image"]:
                continue
            base = allocation_base or descriptor["base"]
            entry = images.get(base)
            if entry is None:
                images[base] = {
                    "base": base,
                    "size": descriptor["size"],
                    "path": descriptor["path"],
                }
            else:
                entry["size"] += descriptor["size"]
                if entry["path"] is None:
                    entry["path"] = descriptor["path"]
    finally:
        w.CloseHandle(handle)

    result = []
    seen = set()
    for entry in sorted(images.values(), key=lambda item: item["base"]):
        path = entry["path"]
        if path is not None:
            key = os.path.normcase(path)
            if key in seen:
                continue
            seen.add(key)
        result.append(entry)
    return result

