    0x04: "rw",    # PAGE_READWRITE
    0x08: "wc",    # PAGE_WRITECOPY
    0x10: "x",     # PAGE_EXECUTE
    0x20: "xr",    # PAGE_EXECUTE_READ
    0x40: "xrw",   # PAGE_EXECUTE_READWRITE
    0x80: "xwc",   # PAGE_EXECUTE_WRITECOPY
}

