# --------------------------------------------------------------------------
# platform, arguments and error classification
# --------------------------------------------------------------------------

def _callable(name):
    return w is not None and getattr(w, name, None) is not None


def _require_platform():
    if _PLATFORM_PROBLEM is not None:
        raise WVasError(_PLATFORM_PROBLEM, kind="unsupported")
    for name in ("OpenProcess", "CloseHandle", "VirtualQueryEx"):
        if not _callable(name):
            raise WVasError(
                "this platform cannot answer address space queries",
                kind="unsupported",
            )


def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid <= 0 or pid > 0xFFFFFFFF:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    return pid


def _fail(message, pid, kinds=None):
    """Classify the last Win32 error and raise the matching :class:`WVasError`."""
    error = w.last_error()
    kind = (kinds or {}).get(error, "query-failed")
    raise WVasError("%s (Win32 error %d)" % (message, error), kind=kind, pid=pid)


def _open_process(pid):
    """Open ``pid`` for reading its address space, classifying every failure."""
    pid = _check_pid(pid)
    _require_platform()
    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, pid
    )
    if not handle:
        _fail(
            "cannot open the process for reading",
            pid,
            kinds={
                w.ERROR_ACCESS_DENIED: "access-denied",
                w.ERROR_INVALID_PARAMETER: "no-such-process",
            },
        )
