        return path[len("\\\\?\\"):]
    return path


def _query_dos_device(name):
    """The NT device names ``name`` (a drive letter) currently points at."""
    if not _callable("QueryDosDeviceW"):
        return []
    buffer = ctypes.create_unicode_buffer(w.MULTI_SZ_CHARS)
    length = w.QueryDosDeviceW(name, buffer, w.MULTI_SZ_CHARS)
    if not length:
        return []
    return w.multi_sz(buffer, length)


