def _final_path(path):
    """The real on-disk path of ``path``, or ``None`` when it cannot be had."""
    if not _callable("CreateFileW") or not _callable("GetFinalPathNameByHandleW"):
        return None
    handle = w.CreateFileW(
        path,
        0,
        w.FILE_SHARE_READ | w.FILE_SHARE_WRITE | w.FILE_SHARE_DELETE,
        None,
        w.OPEN_EXISTING,
        w.FILE_FLAG_BACKUP_SEMANTICS,
        None,
    )
    if not handle or handle == w.INVALID_HANDLE_VALUE:
        return None
    try:
        size = w.MAX_PATH
        while size <= PATH_BUFFER_CHARS:
            buffer = ctypes.create_unicode_buffer(size)
            written = w.GetFinalPathNameByHandleW(
                handle, buffer, size, w.VOLUME_NAME_DOS | w.FILE_NAME_NORMALIZED
            )
            if not written:
                return None
            if written < size:
                resolved = _strip_extended_prefix(buffer.value)
                return resolved if _is_openable(resolved) else None
            size = written + 1
        return None
    finally:
        w.CloseHandle(handle)


class _PathResolver:
    """Works out the file behind a region of one target process.

    The device table, the loader's module table and every name already
    resolved are kept for the lifetime of a single audit: a process has
    hundreds of regions but only a handful of distinct files behind them.
    """

    def __init__(self, handle):
        self._handle = handle
        self._devices = None
        self._by_name = {}
        self._modules = None

    def resolve(self, base, allocation_base, region_type):
        """The openable path of the file behind this region, or ``None``."""
        if region_type == _MEM_IMAGE:
            path = self._module_paths().get(allocation_base)
            if path is None:
                path = self._resolve_name(base)
        else:
            path = self._resolve_name(base)
        return path

    # -- one region --------------------------------------------------------
    def _resolve_name(self, base):
        name = self._mapped_name(base)
        if name is None:
            # Nothing backs this region: an anonymous section, private or
            # reserved memory.  Reporting "" here would read as "a file we
            # could not name" instead of "no file at all".
            return None
        if name in self._by_name:
            return self._by_name[name]
        path = _dos_path(name, self._device_map())
        if path is None or not _is_openable(path):
            path = _final_path(_GLOBALROOT + name)
        if path is not None and not _is_openable(path):
            path = None
        self._by_name[name] = path
        return path

    def _mapped_name(self, base):
        """The NT device name the system gives for the file mapped at ``base``."""
        if not _callable("GetMappedFileNameW"):
            return None
        size = w.MAX_PATH
        while True:
            buffer = ctypes.create_unicode_buffer(size)
            written = w.GetMappedFileNameW(
                self._handle, ctypes.c_void_p(base), buffer, size
            )
            if written:
                return buffer.value or None
            if (
                w.last_error() == w.ERROR_INSUFFICIENT_BUFFER
                and size < PATH_BUFFER_CHARS
            ):
                size *= 4
                continue
            return None

    # -- lazily built tables -----------------------------------------------
    def _device_map(self):
        if self._devices is None:
            self._devices = _dos_device_map()
        return self._devices

    def _module_paths(self):
        if self._modules is None:
            self._modules = _enumerate_module_paths(self._handle)
        return self._modules


def _enumerate_module_paths(handle):
    """``{image base: Win32 path}`` for the images the loader lists."""
    if not _callable("EnumProcessModulesEx") or not _callable("GetModuleFileNameExW"):
        return {}
    paths = {}
    count = 64
    for _ in range(4):
        modules = (ctypes.c_void_p * count)()
        needed = ctypes.wintypes.DWORD(0)
        ok = w.EnumProcessModulesEx(
            handle,
            modules,
            ctypes.sizeof(modules),
            ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        if ok:
            total = needed.value // ctypes.sizeof(ctypes.c_void_p)
            for index in range(min(total, count)):
                base = modules[index] or 0
                if not base or base in paths:
                    continue
                buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
                written = w.GetModuleFileNameExW(
                    handle, ctypes.c_void_p(base), buffer, PATH_BUFFER_CHARS
                )
                if written:
                    name = buffer.value
                    if _is_openable(name):
                        paths[base] = name
            return paths
        if w.last_error() != w.ERROR_BAD_LENGTH:
            return paths
        count *= 4
    return paths


# --------------------------------------------------------------------------
# the walk over the address space
# --------------------------------------------------------------------------

def _address_space_limit():
    if not _callable("GetSystemInfo"):
        return _MAX_APPLICATION_ADDRESS
    info = w.SYSTEM_INFO()
    w.GetSystemInfo(ctypes.byref(info))
    limit = info.lpMaximumApplicationAddress or 0
    return limit if limit > 0 else _MAX_APPLICATION_ADDRESS


def _walk(handle, pid, include_reserved):
    """Yield ``(descriptor, allocation base)`` for every region in use.

    Regions are reported exactly as ``VirtualQueryEx`` measures them -- no
    rounding, no truncation, no merging of neighbours -- so that every number
    can be held next to the one a debugger shows for the same process.
    """
    resolver = _PathResolver(handle)
    limit = _address_space_limit()
    info = w.MEMORY_BASIC_INFORMATION()
    length = ctypes.sizeof(info)
    address = 0
    queried = False

    while address <= limit:
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(info), length
        )
        if not written:
            if not queried:
                _fail(
                    "cannot query the address space",
                    pid,
                    kinds={w.ERROR_ACCESS_DENIED: "access-denied"},
                )
            break
        queried = True

        base = info.BaseAddress or 0
        size = info.RegionSize or 0
        state = info.State
        region_type = info.Type
        allocation_base = info.AllocationBase or base

        if state == w.MEM_COMMIT or (include_reserved and state == w.MEM_RESERVE):
            descriptor = {
                "base": base,
                "size": size,
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(region_type),
                "protect": protection_name(info.Protect),
                "path": None,
                "image": region_type == _MEM_IMAGE,
            }
            if region_type in (_MEM_IMAGE, _MEM_MAPPED):
                descriptor["path"] = resolver.resolve(base, allocation_base, region_type)
            yield descriptor, allocation_base

        step = base + size
        if size == 0 or step <= address:
            break
        address = step


def _audit(pid, include_reserved):
    """Run one audit of ``pid`` and return its descriptors, ascending."""
    handle = _open_process(pid)
    try:
        descriptors = [item for item, _ in _walk(handle, pid, include_reserved)]
    finally:
        w.CloseHandle(handle)
    descriptors.sort(key=lambda item: item["base"])
    return descriptors


# --------------------------------------------------------------------------
# public API
# --------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Committed *and* reserved regions are reported unless ``include_reserved``
    is false; address space that is free is never reported.
    """
    return _audit(pid, True if include_reserved else False)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    One image spans several regions (code, read-only data, writable data), so
    the regions of an image are folded into a single entry keyed by the
    address the image was allocated at.  Each image -- and each file -- is
    reported exactly once.
    """
    handle = _open_process(pid)
    try:
        images = {}
        for descriptor, allocation_base in _walk(handle, pid, False):
            if not descriptor["image"]:
                continue
            base = allocation_base or descriptor["base"]
            entry = images.get(base)
            if entry is None:
                images[base] = {
                    "base": base,
                    "size": descriptor["size"],
                    "path": descriptor["path"],
                }
            else:
                entry["size"] += descriptor["size"]
                if entry["path"] is None:
                    entry["path"] = descriptor["path"]
    finally:
        w.CloseHandle(handle)

    result = []
    seen = set()
    for entry in sorted(images.values(), key=lambda item: item["base"]):
        path = entry["path"]
        if path is not None:
            key = os.path.normcase(path)
            if key in seen:
                continue
            seen.add(key)
        result.append(entry)
    return result
